package vn.rtr.aeris.mission;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.locks.*;
/** Shared bounded cross-instance/JVM lock and no-follow identity boundary. */
public final class JournalGuard17 {
 public static final long WAIT_NS=100000000L;
 public static final class Fact{public final long device,inode,links;public final boolean regular,directory;public Fact(long d,long i,long l,boolean r,boolean f){device=d;inode=i;links=l;regular=r;directory=f;}public boolean same(Fact x){return x!=null&&device==x.device&&inode==x.inode&&links==x.links&&regular==x.regular&&directory==x.directory;}}
 public static class Boundary{
  public Fact fact(File f)throws IOException{Map<String,Object> a=Files.readAttributes(f.toPath(),"unix:dev,ino,nlink,mode",LinkOption.NOFOLLOW_LINKS);int mode=((Number)a.get("mode")).intValue();return new Fact(((Number)a.get("dev")).longValue(),((Number)a.get("ino")).longValue(),((Number)a.get("nlink")).longValue(),(mode&0170000)==0100000,(mode&0170000)==0040000);}
  public void regular(File f)throws IOException{Fact s=fact(f);if(!s.regular||s.links!=1)throw new IOException("JOURNAL17_REGULAR_SINGLE_LINK");}
  public byte[] read(File f,int max)throws IOException{if(f.length()>max)throw new IOException("JOURNAL17_READ_BOUND");return readRange(f,0,(int)f.length(),max);}
  public byte[] readRange(File f,long offset,int count,int maximum)throws IOException{Fact before=fact(f);regular(f);if(offset<0||count<0||count>maximum||offset+count>f.length())throw new IOException("JOURNAL17_READ_BOUND");try(FileChannel c=FileChannel.open(f.toPath(),StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)){ByteBuffer b=ByteBuffer.allocate(count);c.position(offset);while(b.hasRemaining())if(c.read(b)<0)throw new IOException("JOURNAL17_TORN_READ");if(!before.same(fact(f)))throw new IOException("JOURNAL17_READ_IDENTITY_CHANGED");return b.array();}}
  public FileOutputStream append(File f)throws IOException{Fact before=fact(f);regular(f);FileOutputStream out=new FileOutputStream(f,true);if(!before.same(fact(f))){out.close();throw new IOException("JOURNAL17_APPEND_IDENTITY");}return out;}
  public FileOutputStream exclusive(File f)throws IOException{if(!f.createNewFile())throw new IOException("JOURNAL17_EXCLUSIVE");regular(f);return new FileOutputStream(f);}
  public LockFile lockFile(File f)throws IOException{FileChannel c=FileChannel.open(f.toPath(),StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);try{regular(f);return new LockFile(c,c);}catch(IOException e){c.close();throw e;}}
  public void capacity(File root,long add)throws IOException{if(add<0||inputBytes(root)+add>JournalLifecycle17.TOTAL)throw new IOException("JOURNAL17_GLOBAL64MIB_RESERVE");}
  public long inputBytes(File root)throws IOException{long n=0;int[] count={0};for(String name:new String[]{"product-input01",JournalLifecycle17.ARCHIVES,"product-input-lifecycle17","product-input-registry17"}){File f=new File(root,name);if(f.exists())n+=sum(f,count);}return n;}
  private long sum(File f,int[] count)throws IOException{if(++count[0]>1024)throw new IOException("JOURNAL17_ENTRY_BOUND");Fact s=fact(f);if(s.regular){if(s.links!=1)throw new IOException("JOURNAL17_HARDLINK");return f.length();}if(!s.directory)throw new IOException("JOURNAL17_NONREGULAR");File[] fs=f.listFiles();if(fs==null)throw new IOException("JOURNAL17_LIST");long n=0;for(File x:fs)n+=sum(x,count);return n;}
 }
 public static final class LockFile implements AutoCloseable{public final FileChannel channel;private final Closeable close;public LockFile(FileChannel c,Closeable x){channel=c;close=x;}public void close()throws IOException{close.close();}}
 private static final class State{File root;LockFile file;FileLock lock;ReentrantLock mutex;int depth;}
 private static final ThreadLocal<State> HELD=new ThreadLocal<>();private static final ConcurrentHashMap<String,ReentrantLock> LOCAL=new ConcurrentHashMap<>();
 public static final class Scope implements AutoCloseable{private boolean closed;public void close()throws IOException{if(closed)return;closed=true;State s=HELD.get();if(s==null)throw new IOException("JOURNAL17_LOCK_NOT_HELD");if(--s.depth==0){HELD.remove();IOException primary=null;try{s.lock.release();}catch(IOException e){primary=e;}try{s.file.close();}catch(IOException e){if(primary==null)primary=e;else primary.addSuppressed(e);}finally{s.mutex.unlock();}if(primary!=null)throw primary;}}}
 public static Scope enter(File root,Boundary boundary,JournalLifecycle17.Sync sync,long reserve)throws IOException{File canonical=root.getCanonicalFile();if(!canonical.equals(root.getAbsoluteFile()))throw new IOException("JOURNAL17_ROOT_ALIAS");State old=HELD.get();if(old!=null){if(!old.root.equals(canonical))throw new IOException("JOURNAL17_NESTED_OTHER_ROOT");long nestedDeadline=System.nanoTime()+WAIT_NS;boundary.capacity(canonical,reserve);deadline(nestedDeadline);old.depth++;return new Scope();}long deadline=System.nanoTime()+WAIT_NS;ReentrantLock mutex=LOCAL.computeIfAbsent(canonical.getPath(),p->new ReentrantLock());try{if(!mutex.tryLock(WAIT_NS,TimeUnit.NANOSECONDS))throw new IOException("JOURNAL17_LOCAL_LOCK100MS");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException("JOURNAL17_LOCK_INTERRUPTED",e);}LockFile handle=null;FileLock lock=null;boolean admitted=false;try{deadline(deadline);boundary.capacity(canonical,reserve);deadline(deadline);File dir=new File(canonical,"product-input-lifecycle17");if(!dir.exists()){if(!dir.mkdir())throw new IOException("JOURNAL17_LOCK_DIRECTORY");sync.directory(canonical);deadline(deadline);}if(!dir.getCanonicalFile().equals(dir.getAbsoluteFile())||!boundary.fact(dir).directory)throw new IOException("JOURNAL17_LOCK_DIRECTORY_SHAPE");File file=new File(dir,"guard.lock");if(file.exists())boundary.regular(file);deadline(deadline);handle=boundary.lockFile(file);deadline(deadline);while(lock==null){try{lock=handle.channel.tryLock();}catch(OverlappingFileLockException busy){}if(lock!=null)break;if(System.nanoTime()>=deadline)throw new IOException("JOURNAL17_LOCK100MS");try{Thread.sleep(1);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException("JOURNAL17_LOCK_INTERRUPTED",e);}}deadline(deadline);boundary.regular(file);boundary.capacity(canonical,reserve);deadline(deadline);State next=new State();next.root=canonical;next.file=handle;next.lock=lock;next.mutex=mutex;next.depth=1;HELD.set(next);admitted=true;return new Scope();}catch(IOException|RuntimeException|Error e){if(lock!=null)try{lock.release();}catch(IOException x){e.addSuppressed(x);}if(handle!=null)try{handle.close();}catch(IOException x){e.addSuppressed(x);}throw e;}finally{if(!admitted)mutex.unlock();}}
 private static void deadline(long limit)throws IOException{if(System.nanoTime()>=limit)throw new IOException("JOURNAL17_ADMISSION100MS");}
 public static void require(File root)throws IOException{State s=HELD.get();if(s==null||!s.root.equals(root.getCanonicalFile())||s.depth<1)throw new IOException("JOURNAL17_SHARED_LOCK_REQUIRED");}
}
